{
  "profile": "Create AI marketing videos using inference.sh CLI with various video generation and media merging commands.",
  "nodes": [
    {
      "id": "q1",
      "operation": "command.exec",
      "resource": "belt login",
      "summary": "Execute login command for belt CLI",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 20,
        "line_end": 20
      }
    },
    {
      "id": "q2",
      "operation": "command.exec",
      "resource": "belt app run google/veo-3-1-fast --input '{\"prompt\": \"Sleek product reveal video, smartphone emerging from light particles, premium tech aesthetic, commercial quality\"}'",
      "summary": "Generate a product promo video using Veo model",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 23,
        "line_end": 25
      }
    },
    {
      "id": "q3",
      "operation": "command.exec",
      "resource": "belt app run google/veo-3 --input '{\"prompt\": \"Cinematic product launch video, premium tech device floating in space, dramatic lighting, particles and light effects, Apple-style reveal, commercial quality\"}'",
      "summary": "Generate dramatic product reveal video",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 45,
        "line_end": 47
      }
    },
    {
      "id": "q4",
      "operation": "command.exec",
      "resource": "belt app run google/veo-3-1 --input '{\"prompt\": \"Brand story video showing diverse people connecting through technology, warm color grading, lifestyle montage, emotional and inspiring, commercial\"}'",
      "summary": "Generate emotional brand narrative video",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 54,
        "line_end": 56
      }
    },
    {
      "id": "q5",
      "operation": "command.exec",
      "resource": "belt app run bytedance/seedance-2-0 --input '{\"prompt\": \"Close-up product feature demonstration, hands interacting with device, clean background, informative, tech commercial style\", \"generate_audio\": true}'",
      "summary": "Generate feature highlight video with audio",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 63,
        "line_end": 66
      }
    },
    {
      "id": "q6",
      "operation": "command.exec",
      "resource": "belt app run google/veo-3-1-fast --input '{\"prompt\": \"Customer testimonial style video, person speaking to camera, neutral office background, professional lighting, authentic feel\"}'",
      "summary": "Generate talking head testimonial video",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 73,
        "line_end": 75
      }
    },
    {
      "id": "q7",
      "operation": "command.exec",
      "resource": "belt app run google/veo-3-1-fast --input '{\"prompt\": \"Before and after transformation video, split screen transition, dramatic reveal, satisfying comparison, commercial style\"}'",
      "summary": "Generate before and after transformation video",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 82,
        "line_end": 84
      }
    },
    {
      "id": "q8",
      "operation": "command.exec",
      "resource": "belt app run google/veo-3-1-fast --input '{\"prompt\": \"Attention-grabbing opening, product silhouette in dramatic lighting, building anticipation\"}' > hook.json",
      "summary": "Generate opening hook video clip and save to hook.json",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 93,
        "line_end": 95
      }
    },
    {
      "id": "q9",
      "operation": "command.exec",
      "resource": "belt app run google/veo-3-1-fast --input '{\"prompt\": \"Frustrated person dealing with common problem, relatable everyday situation, documentary style\"}' > problem.json",
      "summary": "Generate problem statement video clip and save to problem.json",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 98,
        "line_end": 100
      }
    },
    {
      "id": "q10",
      "operation": "command.exec",
      "resource": "belt app run google/veo-3-1-fast --input '{\"prompt\": \"Product reveal with features highlighted, clean demonstration, solving the problem shown before\"}' > solution.json",
      "summary": "Generate solution reveal video clip and save to solution.json",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 103,
        "line_end": 105
      }
    },
    {
      "id": "q11",
      "operation": "command.exec",
      "resource": "belt app run google/veo-3-1-fast --input '{\"prompt\": \"Happy customer using product, lifestyle integration, multiple quick cuts showing benefits\"}' > benefits.json",
      "summary": "Generate benefits showcase video clip and save to benefits.json",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 108,
        "line_end": 110
      }
    },
    {
      "id": "q12",
      "operation": "command.exec",
      "resource": "belt app run google/veo-3-1-fast --input '{\"prompt\": \"Product hero shot with space for text overlay, professional lighting, commercial ending\"}' > cta.json",
      "summary": "Generate call to action video clip and save to cta.json",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 113,
        "line_end": 115
      }
    },
    {
      "id": "q13",
      "operation": "command.exec",
      "resource": "belt app run infsh/kokoro-tts --input '{\"prompt\": \"Tired of [problem]? Introducing [Product]. [Key benefit 1]. [Key benefit 2]. [Key benefit 3]. Get yours today.\", \"voice\": \"af_nicole\"}' > voiceover.json",
      "summary": "Generate voiceover audio for ad and save to voiceover.json",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 118,
        "line_end": 121
      }
    },
    {
      "id": "q14",
      "operation": "command.exec",
      "resource": "belt app run infsh/media-merger --input '{\"videos\": [\"<hook>\", \"<problem>\", \"<solution>\", \"<benefits>\", \"<cta>\"], \"audio_url\": \"<voiceover>\", \"transition\": \"crossfade\"}'",
      "summary": "Merge video clips and voiceover into final ad video",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 124,
        "line_end": 128
      }
    },
    {
      "id": "q15",
      "operation": "command.exec",
      "resource": "belt app run google/veo-3-1-fast --input '{\"prompt\": \"Fast-paced product showcase, vertical 9:16, quick cuts, trending style, hook in first 2 seconds, satisfying visually, Gen-Z aesthetic\"}'",
      "summary": "Generate Instagram/TikTok style vertical ad video",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 135,
        "line_end": 137
      }
    },
    {
      "id": "q16",
      "operation": "command.exec",
      "resource": "belt app run infsh/media-merger --input '{\"video_url\": \"<video>\", \"audio_url\": \"https://trending-music.mp3\"}'",
      "summary": "Add trendy music to video using media merger",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 140,
        "line_end": 143
      }
    },
    {
      "id": "q17",
      "operation": "command.exec",
      "resource": "belt app run openrouter/claude-sonnet-45 --input '{\"prompt\": \"Write a 60-second explainer video script for a SaaS product. Include: hook, problem, solution, 3 key features, social proof, CTA. Make it conversational.\"}' > script.json",
      "summary": "Generate explainer video script and save to script.json",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 150,
        "line_end": 152
      }
    },
    {
      "id": "q18",
      "operation": "command.exec",
      "resource": "belt app run infsh/kokoro-tts --input '{\"prompt\": \"<full-script>\", \"voice\": \"am_michael\"}' > voiceover.json",
      "summary": "Generate professional voiceover for explainer video",
      "provenance": {
        "file": "SKILL.md",
        "line_start": 164,
        "line_end": 167
      }
    }
  ],
  "edges": [],
  "unresolved": [
    "limitations"
  ]
}

